枚举所有起点 i 与长度 j，用 set<string> 去重即可（n ≤ 100，子串总数最多约 5000，完全可行）。参考程序：

```cpp
#include <iostream>
#include <string>
#include <set>
using namespace std;

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    string s; cin >> s;
    set<string> ss;
    int n = s.length();
    for (int i = 0; i < n; i++)
        for (int j = 1; j <= n - i; j++)
            ss.insert(s.substr(i, j));
    cout << ss.size() << "\n";
    return 0;
}
```

二分答案 D（最小相邻距离），校验能否选出至少 c 座城市，使所有相邻火车站（含起点 0 与终点 m）间距均 ≥ D。贪心：从 0 出发选站，每站须距上一站 ≥ D，且选后仍能保证终点 m 可达（m-a[i] ≥ D）才选，最后检查终点可达与选站数。参考程序：

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

typedef long long ll;
int n, c; ll m;
ll a[1000005];

bool check(ll D) {
    ll last = 0;      // 起点 0 处已建站
    int placed = 0;   // 已选中间城市数
    for (int i = 0; i < n; i++)
        // 距上一站 ≥ D 且选后仍能到达终点才选
        if (a[i] - last >= D && m - a[i] >= D) { last = a[i]; placed++; }
    if (m - last < D) return false; // 终点 m 必须可达
    return placed >= c;
}

int main() {
    ios::sync_with_stdio(false); cin.tie(0);
    cin >> n >> c >> m;
    for (int i = 0; i < n; i++) cin >> a[i];
    sort(a, a + n);
    ll lo = 1, hi = m, ans = 0;
    while (lo <= hi) {
        ll mid = (lo + hi) / 2;
        if (check(mid)) { ans = mid; lo = mid + 1; }
        else hi = mid - 1;
    }
    cout << ans << "
";
    return 0;
}
```
